mapper.select:
WITH stock AS ( SELECT item_cd ,area_cd ,SUM(CASE WHEN tran_date < #{strDate} THEN qty ELSE 0 END) AS baseQty ,SUM(CASE WHEN tran_date BETWEEN #{strDate} AND #{endDate} AND tran_type_cd = 'A' THEN qty ELSE 0 END) AS asQty ,SUM(CASE WHEN tran_date BETWEEN #{strDate} AND #{endDate} AND tran_type_cd = 'E' THEN qty ELSE 0 END) AS makeQty ,SUM(CASE WHEN tran_date BETWEEN #{strDate} AND #{endDate} AND tran_type_cd = 'Q' THEN qty ELSE 0 END) AS qsQty ,SUM(CASE WHEN tran_date BETWEEN #{strDate} AND #{endDate} AND tran_type_cd = 'T' THEN qty ELSE 0 END) AS tsQty ,SUM(CASE WHEN tran_date BETWEEN #{strDate} AND #{endDate} AND tran_type_cd = 'R' THEN qty ELSE 0 END) AS rsQty ,SUM(CASE WHEN tran_date BETWEEN #{strDate} AND #{endDate} AND tran_type_cd IN ('P', 'S', 'V', 'W', 'X', 'U') THEN qty ELSE 0 END) AS etcQty FROM vw_inv_stock_tran WHERE item_type_cd = #{itemTypeCd} AND area_cd = #{areaCd} AND tran_date <= #{endDate} GROUP BY item_cd, area_cd ) SELECT a.item_cd ,a.item_name ,ISNULL(s.baseQty, 0) AS baseQty ,ISNULL(s.asQty, 0) AS asQty ,ISNULL(s.makeQty, 0) AS makeQty ,ISNULL(s.qsQty, 0) AS qsQty ,ISNULL(s.tsQty, 0) AS tsQty ,ISNULL(s.rsQty, 0) AS rsQty ,ISNULL(s.etcQty, 0) AS etcQty ,ISNULL(s.baseQty, 0)+ISNULL(s.asQty, 0)+ISNULL(s.makeQty, 0)+ISNULL(s.qsQty, 0)+ISNULL(s.tsQty, 0)+ISNULL(s.rsQty, 0)+ISNULL(s.etcQty, 0) as qty FROM tb_item_mst a inner JOIN stock s ON s.item_cd = a.item_cd WHERE a.item_type_cd = #{itemTypeCd}
AND a.item_cd LIKE '%' + #{itemCd} + '%'
AND a.item_name LIKE '%' + #{itemName} + '%'
